starts = [331,392,453,514,576,638,699,760,821,882,943,1004]
units=[]
for i,s in enumerate(starts):
    e = starts[i+1] if i+1 < len(starts) else None
    rep = seq[s-1: e+len("GAGTTCCCCGCGCCAGCGGGGATAAACCG")-1 if e else len(seq)]
    core = rep[:32]
    spacer = rep[32:]
    units.append((i+1, s-1, len(spacer), spacer, core))

print("idx | core32 | spacer_len | spacer")
for i,s,sl,sp,core in units:
    print(f"{i:>2}  {core}  {sl:>2}  {'<end of contig>' if sl==0 or not sp else sp}")

# ---- variant repeat analysis ----
core0 = "GAGTTCCCCGCGCCAGCGGGGATAAACCG"
for i,s,sl,sp,core in units:
    mm = [(j,a,b) for j,(a,b) in enumerate(zip(core, core0)) if a!=b]
    print(f"unit {i}: mismatches vs canonical: {mm}")

# ---- do spacers match each other (it could be one duplicated writer / overlapping fragments) ----
print("\nspacers that appear identically >=2 times:", [sp for sp in Counter(sp for _,_,_,sp,_ in units if sp).items() if sp[1]>=1][:5])
c = Counter(sp for _,_,_,sp,_ in units if sp)
dups = {k:v for k,v in c.items() if v>1}
for k,v in dups.items():
    print(f"spacer {k} occurs {v} times -> starts {[i for i,ss,_,sp,_ in units if sp==k]}")

# ---- ORF search ----
stops={'TAA','TAG','TGA'}
def orfs(s):
    out=[]
    for frame in range(3):
        start=None
        for i in range(frame, len(s)-2, 3):
            codon=s[i:i+3]
            if codon in stops:
                if start is not None:
                    out.append((start+1, i+3))
                start=None
            elif start is None:
                start=i
        if start is not None:
            out.append((start+1, len(s)))
    return out

print("\n== ORFs (stop-to-stop) > 200 nt ==")
for strand, s in [('+', seq), ('-', rc(seq))]:
    for a,b in orfs(s):
